<script setup>
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import AppSkeleton from "../../components/common/AppSkeleton.vue"
import AdminIcon from '../../components/admin/AdminIcon.vue'
import AdminSectionHeading from '../../components/admin/AdminSectionHeading.vue'
import {ref,watch} from 'vue'
import {RouterLink,useRoute,onBeforeRouteLeave} from 'vue-router'
import {notificationsApi} from '../../api/notifications.api'
import {useAuthStore} from '../../stores/auth'
import {useOrderPolling} from '../../composables/useOrderPolling'
import {notificationPending,channelLabel,typeLabel} from '../../utils/notificationStatus'
import {formatDateTime} from '../../utils/formatters'
import {normalizeApiError} from '../../utils/apiError'
import NotificationBadge from '../../components/notifications/NotificationBadge.vue'
import NotificationRetry from '../../components/notifications/NotificationRetry.vue'
import ApiPagination from '../../components/admin/catalog/ApiPagination.vue'
const auth=useAuthStore(),route=useRoute(),page=ref(1),active=ref(false),retry=ref(null),notice=ref('')
const state=useOrderPolling(async signal=>{const id=route.params.notificationUuid,notification=await notificationsApi.show(id,signal);let attempts=null,attemptError=null;try{attempts=await notificationsApi.attempts(id,{page:page.value},signal)}catch(cause){if(signal.aborted||[401,403,404].includes(cause.response?.status))throw cause;attemptError=normalizeApiError(cause)}return {notification,attempts,attemptError}},{interval:20000,enabled:()=>auth.can('notifications.view')&&(!state.data.value||notificationPending(state.data.value.notification.status)),paused:()=>active.value})
const {data,loading,refreshing,error,syncedAt}=state
const reload=()=>state.load(true,true)
function changePage(value){page.value=value;void reload()}
function accepted(value){notice.value=value.status==='sent'?'الخادم يؤكد إرسال الإشعار.':value.status==='failed'?'قبل الخادم طلب المحاولة، لكن الحالة الحالية ما زالت متعذرة؛ راجع السبب.':'قُبل طلب إعادة المحاولة؛ لم يتأكد إرسال الرسالة بعد.'}
watch([()=>route.params.notificationUuid,()=>auth.token],()=>{page.value=1;active.value=false;notice.value='';state.reset();if(auth.can('notifications.view'))void state.load()},{immediate:true})
onBeforeRouteLeave(()=>!retry.value?.busy)
</script>
<template><main id="main" class="admin-detail-page"><RouterLink class="row-button" to="/admin/notifications"><AdminIcon name="arrow-left"/> سجل الإشعارات</RouterLink><AdminPageHeader class="page-heading"><h1>تفاصيل الإشعار</h1><button class="button" :disabled="refreshing||active" @click="reload"><AdminIcon name="refresh"/> تحديث الحالة</button></AdminPageHeader><AppSkeleton v-if="refreshing&&!loading" variant="inline" label="جارٍ تحديث البيانات…"/><AppSkeleton v-if="loading" variant="detail" label="جارٍ تحميل الإشعار…"/><div v-if="error" class="panel" role="alert"><p>{{ error.message }}</p><p v-if="data">البيانات من آخر مزامنة؛ تعذر التأكد من الحالة الحالية.</p><button class="button" @click="reload">إعادة المحاولة</button></div><p v-if="notice" role="status">{{ notice }}</p><template v-if="data"><div class="detail-summary-grid"><section class="panel notification-detail detail-record-hero"><h2>{{ typeLabel(data.notification.type) }} · {{ channelLabel(data.notification.channel) }}</h2><NotificationBadge :status="data.notification.status"/><dl class="order-facts"><dt>المستلم</dt><dd dir="ltr">{{ data.notification.recipient }}</dd><dt>اسم المستلم وقت الإشعار</dt><dd>{{ data.notification.recipient_name||'غير مسجل' }}</dd><dt>المزود المسجل</dt><dd>{{ data.notification.provider||'غير مسجل' }}</dd><template v-if="data.notification.provider_message_id"><dt>مرجع الرسالة</dt><dd dir="ltr">{{ data.notification.provider_message_id }}</dd></template><dt>المحاولات المسجلة / الحد الحالي</dt><dd>{{ data.notification.attempts }} / {{ data.notification.max_attempts }}</dd><dt>إنشاء</dt><dd>{{ formatDateTime(data.notification.created_at) }}</dd><template v-if="data.notification.sent_at"><dt>إرسال</dt><dd>{{ formatDateTime(data.notification.sent_at) }}</dd></template><template v-if="data.notification.failed_at"><dt>تعذر</dt><dd>{{ formatDateTime(data.notification.failed_at) }}</dd></template></dl><p v-if="data.notification.last_error" role="status">{{ data.notification.last_error.message }}</p><RouterLink v-if="data.notification.reference?.type==='order'&&auth.can('orders.view')" class="row-button" :to="'/admin/orders/'+data.notification.reference.id">الطلب المرتبط</RouterLink><RouterLink v-if="data.notification.reference?.type==='payment'&&auth.can('payments.view')" class="row-button" :to="'/admin/payments/'+data.notification.reference.id">الدفع المرتبط</RouterLink><NotificationRetry ref="retry" :notification="data.notification" :reload="reload" @active="active=$event" @accepted="accepted"/><p v-if="notificationPending(data.notification.status)">النتيجة لم تُحسم بعد؛ يتم تحديث الحالة كل20 ثانية عندما الصفحة ظاهرة.</p><p v-if="data.notification.status==='sent'">حالة الإرسال مسجلة لدى المطعم؛ لا تعني قراءة المستلم للرسالة.</p><p v-if="syncedAt">آخر مزامنة: {{ formatDateTime(syncedAt) }}</p></section><section v-if="data.notification.content!=null" class="panel notification-detail"><AdminSectionHeading icon="message-circle">محتوى الرسالة وقت الإشعار</AdminSectionHeading><p v-if="data.notification.channel==='email'&&data.notification.subject"><strong>{{ data.notification.subject }}</strong></p><p class="notification-content">{{ data.notification.content }}</p></section></div><section class="panel notification-detail"><AdminSectionHeading icon="clock">محاولات الإرسال</AdminSectionHeading><p>سجل للقراءة فقط؛ قبول طلب إعادة المحاولة لا يؤكد إرسال الرسالة.</p><p v-if="data.attemptError" role="alert">{{ data.attemptError.message }}</p><template v-if="data.attempts"><ol class="notification-attempts"><li v-for="attempt in data.attempts.data" :key="attempt.id"><h3>محاولة {{ attempt.attempt_number }} · {{ attempt.manual?'بطلب موظف':'تلقائية' }}</h3><NotificationBadge :status="attempt.status"/><p>المزود: {{ attempt.provider||'غير مسجل' }}</p><p>بدأت: {{ formatDateTime(attempt.started_at) }}</p><p>{{ attempt.finished_at?'انتهت: '+formatDateTime(attempt.finished_at):'لم تنتهِ المحاولة بعد.' }}</p><p v-if="attempt.provider_message_id">مرجع الرسالة: <span dir="ltr">{{ attempt.provider_message_id }}</span></p><p v-if="attempt.error">{{ attempt.error.message }}</p></li></ol><p v-if="!data.attempts.data.length">لا توجد محاولات مسجلة بعد.</p><ApiPagination :meta="data.attempts.meta" :links="data.attempts.links" :busy="refreshing||active" @page="changePage"/></template></section></template></main></template>

